(* [comment removed for export] *)
Definition sel_cells (m : word -> option byte) (sv : selv) (c : Z -> Z -> Z) : Prop :=
  forall i j, (0 <= i < v_sy sv)%Z -> (0 <= j < v_sx sv)%Z ->
    rdn SEGS m (Z_to_bv 64 (v_rows sv i + 4 * j)) 4 = Some (Z_to_le_bytes 4 (c i j)).

