Lemma tsw_blk : forall C A m md (p n : Z), Cok C -> W C A m md -> live A (Z_to_bv 64 p) = Some n -> (0 <= p < 2 ^ 64)%Z -> (0 < n)%Z ->
  bok (alloc_top (c_vm C)) p n /\ (p + n < 2 ^ 47)%Z /\ (forall i, (0 <= i < n)%Z -> m (Z_to_bv 64 (p + i)) <> None).
Proof.
