Lemma tsw_bytes : forall m (a : Z) (k : nat) (v : Z), (0 <= a)%Z -> (a + Z.of_nat k <= 2 ^ 64)%Z ->
  (forall i, (0 <= i < Z.of_nat k)%Z -> m (Z_to_bv 64 (a + i)) <> None) ->
  rdn SEGS m (Z_to_bv 64 a) k = Some (Z_to_le_bytes k v) -> bytes_at m a (Z_to_le_bytes k v).
Proof.
