Lemma tsw_rec : forall m (sel sy sx cy cx data name : Z), (0 <= sel)%Z -> (sel + 32 < 2 ^ 64)%Z ->
  (forall i, (0 <= i < 32)%Z -> m (Z_to_bv 64 (sel + i)) <> None) ->
